#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>

int main(int argc, char * argv[]) {
    @autoreleasepool {
        // Get the shared application
        UIApplication *app = [UIApplication sharedApplication];

        // Find and print the active windows
        NSArray *windows = [app windows];
        NSLog(@"Windows: %ld", (long)[windows count]);

        for (UIWindow *window in windows) {
            NSLog(@"Window: %@", window);
            NSLog(@"Root view controller: %@", [window rootViewController]);
        }

        // Try to find alert controllers
        UIViewController *root = [[app keyWindow] rootViewController];
        NSLog(@"Key window root: %@", root);

        // Try to dismiss any presented view controller
        if ([root presentedViewController]) {
            NSLog(@"Found presented view controller: %@", [root presentedViewController]);
            [root dismissViewControllerAnimated:NO completion:^{
                NSLog(@"Dismissed!");
            }];
        }
    }
    return 0;
}
EOF

